import {speechChunks} from './speech-extract.js';import {read,put} from './project-store.js';
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n},button=(text,fn,cls='')=>{const b=el('button',cls,text);b.type='button';b.onclick=fn;return b};
const hash=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');
const base64=bytes=>{let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s)};
export async function recognizeChunk(wave,language,model,{admin=false}={}){const key='asr:'+await hash(new TextEncoder().encode(model+'|'+language+'|'+await hash(wave))),saved=await read(key);if(saved?.result)return {...saved.result,cached:true};const id=saved?.id||crypto.randomUUID();await put(key,{id});let response;try{response=await fetch(admin?'/api/admin/transcription/test':'/api/transcription',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Idempotency-Key':id},body:JSON.stringify({audio:base64(wave),language}),signal:AbortSignal.timeout(65000)})}catch{throw Error('Связь прервалась. Повторный запуск проверит тот же запрос без повторного списания.')}const data=await response.json();if(!response.ok){if(response.status!==409)await put(key,{id:null});throw Error(data.error||'Распознавание не завершено.')}await put(key,{id,result:data});return data}
export function mountTranscription(api){let running=false;const {getState,getAssets,commit,pause,creationAllowed,refreshMembership}=api;
 async function open(){if(running||!creationAllowed())return;pause();const snapshot=structuredClone(getState()),fingerprint=JSON.stringify(snapshot.clips),duration=snapshot.clips.reduce((n,c)=>n+(c.end-c.start)/c.speed,0);if(!duration){api.toast('Сначала добавьте видео с речью на таймлайн.');return}const d=el('dialog','transcription-dialog editor-control-dialog'),header=el('div','control-heading'),close=button('×',()=>d.close());close.setAttribute('aria-label','Закрыть распознавание');header.append(el('h2','','Субтитры из речи'),close);d.append(header,el('p','','Программа извлечёт звук из сцен таймлайна и распознает произнесённые слова с таймкодами. Музыка отдельной дорожки не отправляется. Исходные видео не изменятся.'));const summary=el('p','asr-summary','Проверяем подключение…'),language=el('select'),style=el('select');for(const [id,name]of [['ru','Русский'],['auto','Определить язык'],['en','Английский']]){const o=el('option','',name);o.value=id;language.append(o)}language.setAttribute('aria-label','Язык распознавания');for(const [id,name]of [['karaoke','Reels · выделение текущего слова'],['outline','Крупные · контур'],['plate','Спокойные · подложка']]){const o=el('option','',name);o.value=id;style.append(o)}style.setAttribute('aria-label','Стиль речевых субтитров');const clear=el('input');clear.type='checkbox';clear.checked=true;const clearLabel=el('label','asr-check');clearLabel.append(clear,document.createTextNode('Убрать постоянные заголовки сцен; оставить речевые субтитры'));const consent=el('input');consent.type='checkbox';const consentLabel=el('label','asr-check');consentLabel.append(consent,document.createTextNode('Отправить звуковую дорожку сервису распознавания OpenRouter'));const progress=el('progress');progress.max=100;progress.value=0;const status=el('p','control-status');status.setAttribute('role','status');d.append(summary,language,style,clearLabel,consentLabel,progress,status);let cfg,stopped=false;const footer=el('div','control-footer'),cancel=button('Отмена',()=>{if(running){stopped=true;status.textContent='Остановим после текущего фрагмента. Готовая расшифровка сохранится для повторного запуска.'}else d.close()}),run=button('Распознать и добавить субтитры',async()=>{if(running||!cfg?.ready||!consent.checked)return;running=true;run.disabled=true;language.disabled=style.disabled=consent.disabled=clear.disabled=true;close.disabled=true;const cues=[];try{let index=0;for await(const chunk of speechChunks(snapshot,getAssets(),{stop:()=>stopped})){index++;status.textContent=`Распознаём фрагмент ${index} из ${Math.ceil(duration/30)}…`;const result=chunk.silent?{cues:[],noSpeech:true}:await recognizeChunk(chunk.wave,language.value,cfg.model);for(const c of result.cues)cues.push({...c,start:c.start+chunk.offset,end:c.end+chunk.offset,...(c.words?{words:c.words.map(w=>({...w,start:w.start+chunk.offset,end:w.end+chunk.offset}))}:{})});progress.value=Math.min(100,(chunk.offset+chunk.duration)/duration*100);if(stopped)break}if(stopped){status.textContent='Остановлено. Готовые фрагменты сохранены: повторный запуск использует их без повторной оплаты.';return}if(!cues.length)throw Error('Разборчивая речь не обнаружена. Субтитры не подменялись заголовком.');if(getState().projectId!==snapshot.projectId||JSON.stringify(getState().clips)!==fingerprint)throw Error('Таймлайн изменился. Запустите распознавание снова; готовые фрагменты будут взяты из кэша.');await document.fonts.load('700 40px "Roboto Condensed"');commit(()=>{const s=getState();s.cues=cues;s.captionsEnabled=true;s.captionStyle={font:'Roboto Condensed',size:6.5,position:'bottom',style:style.value,safe:18};s.transcript={model:cfg.model,createdAt:new Date().toISOString(),text:cues.map(c=>c.text).join(' ')};if(clear.checked)s.clips.forEach(c=>c.title='')});status.textContent=`Готово: ${cues.length} коротких реплик. Можно поправить текст, время и оформление во вкладке «Субтитры».`;run.textContent='Субтитры добавлены';api.toast('Речь распознана. Субтитры добавлены на таймлайн.')}catch(e){status.textContent=e.message;run.disabled=false}finally{running=false;stopped=false;close.disabled=false;language.disabled=style.disabled=consent.disabled=clear.disabled=false;await refreshMembership?.()}},'primary');run.disabled=true;consent.onchange=()=>run.disabled=!cfg?.ready||!consent.checked;footer.append(cancel,run);d.append(footer);d.addEventListener('close',()=>{stopped=true;d.remove()});document.body.append(d);d.showModal();try{const r=await fetch('/api/transcription/settings');cfg=await r.json();if(!r.ok)throw Error(cfg.error);summary.textContent=cfg.ready?`${duration.toFixed(1)} сек · ${cfg.cost} кр. за фрагмент до 30 сек · максимум ${Math.ceil(duration/30)*cfg.cost} кр. Готовые фрагменты повторно не оплачиваются.`:'Сервис распознавания пока выключен или не подключён. Администратору: ИИ и скиллы → Распознавание речи.';run.disabled=!cfg.ready||!consent.checked}catch(e){summary.textContent=e.message}}
 const captionPane=document.querySelector('#inspect-captions'),launch=button('Распознать речь из видео',open,'primary');launch.id='transcribe-open';captionPane.prepend(launch);const toolbar=document.querySelector('.viewer-toolbar>div:first-child');toolbar.append(button('Автосубтитры',open));return {open};
}
